def two_missing(a):
    combined = 0
    for value in range(len(a) + 2):
        combined ^= value
    for value in a:
        combined ^= value
    partition = combined & -combined
    first = second = 0
    for value in range(len(a) + 2):
        if value & partition:
            first ^= value
        else:
            second ^= value
    for value in a:
        if value & partition:
            first ^= value
        else:
            second ^= value
    return [first, second]

