def permutations(text):
    frequencies = {}
    for char in text:
        frequencies[char] = frequencies.get(char, 0) + 1
    out = []
    def visit(prefix):
        if len(prefix) == len(text):
            out.append(prefix)
            return
        for char in frequencies:
            if frequencies[char]:
                frequencies[char] -= 1
                visit(prefix + char)
                frequencies[char] += 1
    visit('')
    return out

function permutations(text) {
  const chars = Array.from(text), counts = new Map(), out = [];
  for (const char of chars) counts.set(char, (counts.get(char) ?? 0) + 1);
  function visit(path) {
    if (path.length === chars.length) { out.push(path.join('')); return; }
    for (const [char, count] of counts) if (count > 0) {
      counts.set(char, count - 1); path.push(char); visit(path); path.pop(); counts.set(char, count);
    }
  }
  visit([]);
  return out;
}

